    pcv rax sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 (ra s0v s1v s2v s3v s4v s5 s6 : word) s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P verb MP TP At ver lo shi : Z) (mbs tbs : list byte) (h : hdrv) (junk j8 : list byte),
  (pcv = Z_to_bv 64 ART_RET1 \/ pcv = ret_pc (Z_to_bv 64 ART_RET1)) ->
  req_frames m sp ra s0v s1v s2v s3v s4v s5 j8 TP (Z.of_nat (length tbs)) P verb MP (Z.of_nat (length mbs)) ver AWK_RET_RT ->
  rw_cells bsegs m (P + O_PR_HDR) (HdrCells h) -> hdr_empty h ->
  rw_cells bsegs m At [CB (Z.to_nat (Z.of_nat (length tbs) + 1)) junk] ->
  In (pt, At, Z.of_nat (length tbs) + 1) LB -> addressable m At (Z.of_nat (length tbs) + 1) ->
  bytes_at bsegs m MP mbs -> bytes_at bsegs m TP tbs ->
  (TP + Z.of_nat (length tbs) <= At \/ At + (Z.of_nat (length tbs) + 1) <= TP) ->
  (MP + Z.of_nat (length mbs) <= At \/ At + (Z.of_nat (length tbs) + 1) <= MP) ->
  (P + 256 <= At \/ At + (Z.of_nat (length tbs) + 1) <= P) ->
  (MP + Z.of_nat (length mbs) <= P \/ P + 256 <= MP) -> (TP + Z.of_nat (length tbs) <= P \/ P + 256 <= TP) ->
  stk bsegs m lo (bv_unsigned sp + -144) ->
  req_pure sp P MP TP lo mbs tbs -> 0 <= verb < 2^32 -> verb = verb_of (zbytes mbs) -> (ver = 10 \/ ver = 11) -> mem_inv bsegs m ->
  bv_unsigned ra mod 2 = 0 ->
  (* [comment removed for export] *)
  tp = Z_to_bv 64 ATP -> ACONST m -> as_RHEAP H s LB m -> as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp <= shi ->
  0 <= P -> aobj LB LF P 256 -> accessible m P 256 ->
  aobj LB LF MP (Z.of_nat (length mbs)) -> accessible m MP (Z.of_nat (length mbs)) ->
  aobj LB LF TP (Z.of_nat (length tbs)) -> accessible m TP (Z.of_nat (length tbs)) ->
  evt bsegs (req_seg2_post ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc s LB LF P verb MP TP At ver lo shi mbs tbs h m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz (P + 144)) (wz (P + 152)) (wz At) a1 a2 a3 a4 a5 a6 a7
              (wz MP) (wz (Z.shiftr (P + 152) 3 + 2147450880)) (wz 2147450880) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F pcv fc None m (seg_rom bsegs)).

Lemma req_seg2 : req_seg2_stmt.
Proof.
  intros until j8. intros PC0 FRS HDR HE BLK INB ADB MB TB SEPT SEPM SEPP SPM SPT ST PURE VB VERB VER MI RA TPV AC RH RF LFN SK SHI P0 AOP ACP AOM ACM AOT ACT.
  eapply evt_cut.
  { eapply (rt_after H HH FS0); fast_eassumption. }
  intros ms' POST.
  destruct POST as (t0x & t1x & t2x & a0x & a1x & a2x & a3x & a4x & a5x & a6x & a7x & t3x & t4x & t5x & t6x & m1 & XS0
                    & E & MU0 & FSX0 & WM0 & MI1 & ST1 & FRT & FRW & HDR1 & BLK1 & MB1 & TB1 & RH1 & RF1 & AC1 & SK1 & ACP1 & ACM1 & ACT1). subst ms'.
  eapply (wk_rest s LB LF pt XS0); try fast_eassumption.
Qed.

End HCW.
